import{I as i,o as d,c as u,j as e,a as o,J as n,w as s,b6 as m}from"./chunks/framework.BUXTSoD9.js";const g={style:{margin:"50px 0"}},q=JSON.parse('{"title":"Encontrar buenas ideas - De las necesidades de los usuarios a quienes estan dispuestos a pagar","description":"Aprende a descubrir oportunidades a partir de dolores cotidianos, evaluar si alguien pagara y convertir una idea en un concepto de producto ejecutable.","frontmatter":{"title":"Encontrar buenas ideas - De las necesidades de los usuarios a quienes estan dispuestos a pagar","description":"Aprende a descubrir oportunidades a partir de dolores cotidianos, evaluar si alguien pagara y convertir una idea en un concepto de producto ejecutable."},"headers":[],"relativePath":"es-es/stage-1/finding-great-idea/index.md","filePath":"es-es/stage-1/finding-great-idea/index.md"}'),h={name:"es-es/stage-1/finding-great-idea/index.md"},P=Object.assign(h,{setup(b){const t="Aprox. <strong>3 horas</strong>";return(v,a)=>{const r=i("ChapterIntroduction"),l=i("StepBar"),c=i("ClientOnly"),p=i("RelatedArticlesSection");return d(),u("div",null,[a[1]||(a[1]=e("h1",{id:"principiante-2-encontrar-buenas-ideas",tabindex:"-1"},[o("Principiante 2: Encontrar buenas ideas "),e("a",{class:"header-anchor",href:"#principiante-2-encontrar-buenas-ideas","aria-label":"Permalink to “Principiante 2: Encontrar buenas ideas”"},"​")],-1)),a[2]||(a[2]=e("h2",{id:"introduccion-del-capitulo",tabindex:"-1"},[o("Introduccion del capitulo "),e("a",{class:"header-anchor",href:"#introduccion-del-capitulo","aria-label":"Permalink to “Introduccion del capitulo”"},"​")],-1)),n(r,{duration:t,tags:["Descubrimiento de necesidades","Pensamiento de producto","Analisis de usuarios","Modelo de negocio"],coreOutput:"3 conceptos de producto validados",expectedOutput:"Una direccion de emprendimiento/producto ejecutable"},{default:s(()=>[...a[0]||(a[0]=[e("p",null,[o("Ya aprendiste a construir con un AI IDE, pero la pregunta mas importante es: "),e("strong",null,"que construir?")],-1),e("p",null,[o('Mucha gente empieza con "hagamos una herramienta de IA" o "montemos una plataforma social" y termina con algo que nadie usa. El motivo mas comun es simple: '),e("strong",null,"no habia una necesidad real"),o(".")],-1),e("p",null,[o("Incluso si el producto resuelve algo, todavia queda la parte dificil: "),e("strong",null,"que el usuario pague"),o(".")],-1),e("p",null,"En este capitulo, a traves de un caso y un conjunto de marcos practicos, aprenderas un metodo para encontrar ideas y convertirlas en conceptos validables.",-1)])]),_:1}),e("div",g,[n(c,null,{default:s(()=>[n(l,{active:0,items:[{title:"Step 1",description:"Definir criterios"},{title:"Step 2",description:"Encontrar dolores cotidianos"},{title:"Step 3",description:"Segmentar audiencias"},{title:"Step 4",description:"Profundizar escenarios"},{title:"Step 5",description:"Validar si es real"},{title:"Step 6",description:"Pulir el concepto"}]})]),_:1})]),a[3]||(a[3]=m(`<h2 id="step-1-definir-criterios-cuando-paga-la-gente" tabindex="-1">Step 1: Definir criterios (cuando paga la gente?) <a class="header-anchor" href="#step-1-definir-criterios-cuando-paga-la-gente" aria-label="Permalink to “Step 1: Definir criterios (cuando paga la gente?)”">​</a></h2><p>Un error tipico es evaluar ideas por &quot;me gusta&quot; o &quot;suena bien&quot;. Lo que buscamos es <strong>voluntad de pago</strong>.</p><p>Usa este checklist:</p><ol><li>Dolor fuerte: frecuente, caro, riesgoso o estresante.</li><li>Usuario claro: puedes describir quien es en una frase.</li><li>Escenario concreto: cuando y donde ocurre el problema.</li><li>Alternativas malas: hoy se resuelve con friccion o con soluciones incompletas.</li><li>Beneficio medible: ahorra tiempo/dinero, reduce riesgo o aumenta ingresos.</li></ol><div class="warning custom-block"><p class="custom-block-title">Importante</p><p>No preguntes &quot;Usarias esto?&quot; Esa pregunta produce falsos positivos. Pregunta por comportamiento real: &quot;Como lo resuelves hoy?&quot;, &quot;Cuantas veces te paso esta semana?&quot;, &quot;Cuanto te costo en tiempo o dinero?&quot;</p></div><h2 id="step-2-encontrar-dolores-cotidianos" tabindex="-1">Step 2: Encontrar dolores cotidianos <a class="header-anchor" href="#step-2-encontrar-dolores-cotidianos" aria-label="Permalink to “Step 2: Encontrar dolores cotidianos”">​</a></h2><p>Las mejores ideas vienen de problemas repetidos.</p><p>Fuentes practicas:</p><ul><li>Tu trabajo: reportes, coordinacion, aprobaciones, QA, despliegues.</li><li>Tu vida: salud, finanzas, estudio, viajes, familia.</li><li>Nichos: industria con regulacion, facturacion, soporte, operaciones.</li></ul><p>Ejercicio rapido:</p><ol><li>Escribe 20 molestias reales que hayas visto en el ultimo mes.</li><li>Elige 5 que ocurran semanalmente.</li><li>Para cada una, anota quien lo sufre y que alternativa usa hoy.</li></ol><h2 id="step-3-segmentar-audiencias-horizontal" tabindex="-1">Step 3: Segmentar audiencias (horizontal) <a class="header-anchor" href="#step-3-segmentar-audiencias-horizontal" aria-label="Permalink to “Step 3: Segmentar audiencias (horizontal)”">​</a></h2><p>Un mismo problema tiene distinta voluntad de pago segun la persona.</p><p>Ejemplo: &quot;organizar archivos&quot; no paga casi nadie; pero &quot;organizar documentos para auditoria&quot; lo paga una empresa.</p><p>Hazlo asi:</p><ol><li>Lista 3-5 grupos posibles de usuarios.</li><li>Para cada grupo, define: objetivo, contexto, restricciones, presupuesto.</li><li>Elige 1 grupo donde el dolor sea mas caro o mas urgente.</li></ol><h2 id="step-4-profundizar-escenarios-vertical" tabindex="-1">Step 4: Profundizar escenarios (vertical) <a class="header-anchor" href="#step-4-profundizar-escenarios-vertical" aria-label="Permalink to “Step 4: Profundizar escenarios (vertical)”">​</a></h2><p>No disenes &quot;una app&quot;. Disena <strong>un flujo</strong> que resuelva un escenario completo.</p><p>Plantilla:</p><ul><li>Disparador: que pasa para que el usuario necesite la solucion?</li><li>Pasos actuales: que hace hoy (y que le molesta)?</li><li>Momento de valor: en que minuto entiende que le ahorraste algo?</li><li>Resultado: que cambia al final?</li></ul><h2 id="step-5-validar-si-es-real-antes-de-construir" tabindex="-1">Step 5: Validar si es real (antes de construir) <a class="header-anchor" href="#step-5-validar-si-es-real-antes-de-construir" aria-label="Permalink to “Step 5: Validar si es real (antes de construir)”">​</a></h2><p>Objetivo: validar 2 cosas.</p><ol><li>Existe el problema (frecuencia e impacto).</li><li>Existe voluntad de pago o al menos una accion fuerte (dejar email, reservar, prepagar).</li></ol><p>Metodos de bajo costo:</p><ul><li>10 entrevistas con usuarios objetivo (30 min cada una).</li><li>Landing simple con propuesta de valor y CTA (lista de espera / reserva).</li><li>Demo clickable o prototipo y medir conversion.</li><li>Pre-venta o deposito (la validacion mas honesta).</li></ul><h2 id="step-6-pulir-el-concepto-con-ia" tabindex="-1">Step 6: Pulir el concepto con IA <a class="header-anchor" href="#step-6-pulir-el-concepto-con-ia" aria-label="Permalink to “Step 6: Pulir el concepto con IA”">​</a></h2><p>Aqui la IA ayuda a convertir una intuicion en un concepto ejecutable.</p><p>Prompt para copiar:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Actua como consultor de producto. Quiero refinar una idea.</span></span>
<span class="line"><span>1) Usuario objetivo:</span></span>
<span class="line"><span>2) Dolor principal:</span></span>
<span class="line"><span>3) Escenario concreto (cuando/donde):</span></span>
<span class="line"><span>4) Solucion actual y por que es mala:</span></span>
<span class="line"><span>5) Propuesta de valor en una frase:</span></span>
<span class="line"><span>6) MVP en 7 dias:</span></span>
<span class="line"><span>7) Riesgos/objeciones:</span></span>
<span class="line"><span>8) Plan de validacion y metricas:</span></span>
<span class="line"><span>Devuelveme: (a) concepto pulido, (b) alcance del MVP, (c) plan de validacion en 7 dias.</span></span></code></pre></div><h2 id="salida-esperada-3-conceptos-de-producto" tabindex="-1">Salida esperada: 3 conceptos de producto <a class="header-anchor" href="#salida-esperada-3-conceptos-de-producto" aria-label="Permalink to “Salida esperada: 3 conceptos de producto”">​</a></h2><p>Al final, deberias tener 3 conceptos, cada uno con:</p><ul><li>Usuario objetivo claro</li><li>Problema concreto</li><li>Propuesta de valor en una frase</li><li>MVP (1-2 semanas)</li><li>Experimento de validacion y metricas</li></ul>`,32)),n(p)])}}});export{q as __pageData,P as default};
